using UnityEngine;

// 생산시설: 시간이 차면 골드를 벌어요. 레벨이 높을수록 한 번에 버는 골드가 레벨에 비례해 늘어요.
// 레벨 · 골드는 모두 소지품(Inventory)에 숫자로 들어 있어서 버튼 · 매니저 스크립트와 함께 써요.
// 쓰인 코드: Update · Time.deltaTime · Inventory · GetComponent<Animator>() · SetTrigger · UIScreen.SetText / SetValue
public class Facility : MonoBehaviour
{
    [Header("이 시설")]
    public string id = "빵";            // 소지품 이름 "빵 레벨" · UI 그룹 "빵 줄"(정보 · 진행)
    [Tooltip("1레벨일 때 한 번 생산하면 버는 골드")]
    public int income = 1;
    [Tooltip("한 번 생산하는 데 걸리는 시간 (초)")]
    public float interval = 1.5f;

    float timer = 0f;
    Animator anim;

    void Start()
    {
        anim = GetComponent<Animator>();
    }

    void Update()
    {
        string row = id + " 줄";                          // 이 시설의 UI 그룹 (계층 구조 UI › 빵 줄)
        int level = Inventory.Count(id + " 레벨");
        if (level == 0)                                   // 아직 열지 않은 시설
        {
            UIScreen.SetText(row, "정보", "잠김 · 열면 생산해요");
            UIScreen.SetValue(row, "진행", 0);
            return;
        }

        // 강화 효과: 「빠른 손」은 생산 시간을, 「단골 손님」은 판매 가격을 바꿔요
        int speedLv = Inventory.Count("속도 레벨");
        int priceLv = Inventory.Count("가격 레벨");
        float time = interval / (1f + 0.25f * speedLv);
        int earn = income * level * (100 + 50 * priceLv) / 100;   // 레벨에 비례

        timer += Time.deltaTime;
        if (timer >= time)
        {
            timer -= time;
            Inventory.Add("골드", earn);
            Inventory.Add("판매", 1);
            anim.SetTrigger("Make");                      // 통통 튀는 생산 애니메이션
        }

        UIScreen.SetValue(row, "진행", timer / time);
        UIScreen.SetText(row, "정보", "Lv " + level + " · +" + earn + "G / " + Mathf.Round(time * 10f) / 10f + "초");
    }
}

using UnityEngine;

// 업그레이드 버튼 (UI 버튼에 붙어 있어요): 누르면 골드를 내고 레벨을 1 올려요.
// 비용은 레벨이 오를수록 growth 배씩 비싸져요. 골드가 모자라면 버튼이 회색이 돼요.
// 버튼 글자는 버튼 위에 놓인 텍스트 요소 「버튼 글」이라서, 배경색과 글자색을 따로 바꿔 늘 잘 보이게 해요.
// 쓰인 코드: OnClick · Update(UI 스크립트) · Mathf.Pow · Mathf.RoundToInt · UIScreen.SetText / SetColor · Message.Show
public class UpgradeButton : MonoBehaviour
{
    public string id = "빵";             // 올릴 레벨: 소지품 "빵 레벨"
    public string title = "빵 오븐";
    public int baseCost = 8;              // 0레벨 → 1레벨 비용
    public float growth = 1.45f;          // 레벨마다 비용이 몇 배씩 오르나
    [Tooltip("시설이 아닌 강화(속도 · 가격)면 정보 줄을 이 스크립트가 써요")]
    public string effect = "";            // 예: "생산 속도"
    public int perLevel = 0;              // 예: 25 → 레벨마다 +25%

    int Cost()
    {
        int lv = Inventory.Count(id + " 레벨");
        return Mathf.RoundToInt(baseCost * Mathf.Pow(growth, lv));
    }

    void Update()
    {
        int lv = Inventory.Count(id + " 레벨");
        int cost = Cost();
        string row = id + " 줄";                          // 이 버튼이 들어 있는 UI 그룹
        string verb = (lv == 0 && effect == "") ? "열기" : "강화";
        bool canBuy = Inventory.Count("골드") >= cost;

        UIScreen.SetText(row, "버튼 글", verb + " " + cost + "G");
        UIScreen.SetColor(row, "버튼", canBuy ? "#e9bd0c" : "#343842");      // 버튼 배경
        UIScreen.SetColor(row, "버튼 글", canBuy ? "#1a1400" : "#8b909c");   // 버튼 글자

        if (effect != "")
        {
            UIScreen.SetText(row, "정보", "Lv " + lv + " · " + effect + " +" + (perLevel * lv) + "%");
        }
    }

    public void OnClick()
    {
        int cost = Cost();
        if (Inventory.Count("골드") < cost)
        {
            Message.Show("골드가 " + (cost - Inventory.Count("골드")) + "G 모자라요");
            return;
        }
        Inventory.Remove("골드", cost);
        Inventory.Add(id + " 레벨", 1);
        Message.Show(title + " Lv " + Inventory.Count(id + " 레벨") + "!");
        Debug.Log(title + " 강화 → Lv " + Inventory.Count(id + " 레벨") + " (" + cost + "G 사용)");
    }
}

using UnityEngine;

// 가게 매니저: 처음 상태를 정하고, 위쪽 골드 · 가게 정보 UI를 매 프레임 바꿔요.
public class ShopManager : MonoBehaviour
{
    public int startGold = 0;

    void Start()
    {
        Inventory.Add("빵 레벨", 1);          // 빵 오븐은 처음부터 1레벨
        Inventory.Add("골드", startGold);
        Debug.Log("고양이 빵집 영업 시작!");
    }

    void Update()
    {
        int gold = Inventory.Count("골드");
        int shopLv = Inventory.Count("빵 레벨") + Inventory.Count("커피 레벨") + Inventory.Count("케이크 레벨")
                   + Inventory.Count("속도 레벨") + Inventory.Count("가격 레벨");

        UIScreen.SetText("HUD", "골드", gold + " G");
        UIScreen.SetText("HUD", "가게 정보", "가게 Lv " + shopLv + " · 판매 " + Inventory.Count("판매") + "개");
    }
}

using UnityEngine;

// 업그레이드 판 접기 / 펼치기 (판 머리의 「접기」 버튼과, 접었을 때 보이는 「업그레이드」 탭 버튼에 붙어 있어요)
// UI 그룹을 통째로 숨기고 보여 줘요. 쓰인 코드: OnClick · UIScreen.Show / Hide · 직접 만든 메서드
public class PanelToggle : MonoBehaviour
{
    [Tooltip("켜면 이 버튼이 판을 펼치고, 끄면 접어요")]
    public bool open = false;

    public void OnClick()
    {
        Row("업그레이드 판", open);
        Row("빵 줄", open);
        Row("커피 줄", open);
        Row("케이크 줄", open);
        Row("속도 줄", open);
        Row("가격 줄", open);
        Row("업그레이드 열기", !open);       // 접혀 있을 때만 보이는 탭
    }

    // ▼ 직접 만든 메서드: on이면 그 UI 그룹을 보이고, 아니면 숨겨요
    void Row(string group, bool on)
    {
        if (on) UIScreen.Show(group);
        else UIScreen.Hide(group);
    }
}

using UnityEngine;

// 주인공 이동 스크립트 (타일형)
// 주인공 컴포넌트를 추가하면 기본으로 붙습니다. 방향키/WASD를 누르면 칸 가운데에서 옆 칸 가운데로 한 칸씩 걸어갑니다 (좀비고처럼).
// 짧게 누르면 딱 한 칸, holdDelay(초)보다 오래 누르고 있으면 멈추지 않고 칸 단위로 이어서 걷습니다.
// 대각선 없이 상하좌우로만 움직입니다.
// 막힌 칸(벽 · NPC · 박스 콜라이더)으로는 가지 않고 그쪽을 바라보기만 합니다.
// 칸에 묶이지 않고 픽셀 단위로 부드럽게 움직이려면 컴포넌트 추가에서 「주인공 이동 (픽셀형)」으로 바꾸세요.
// 걷기·대기 그림은 애니메이터 컴포넌트가 정합니다. 이 스크립트는 애니메이터 파라미터
// IsMoving(걷는 중인지)과 Dir(0 아래 · 1 위 · 2 왼쪽 · 3 오른쪽)만 바꿔 줍니다.
// 좌표: 오른쪽이 +x, 아래쪽이 +y 입니다 (단위: 칸 · 정수 좌표가 칸 가운데).
public class HeroTileMovement : MonoBehaviour
{
    [Header("이동")]
    [Tooltip("1초에 이동하는 칸 수입니다")]
    public float speed = 5f;

    [Tooltip("이 시간(초)보다 오래 누르고 있으면 계속 걷습니다. 그보다 짧게 누르면 한 칸만 갑니다")]
    [Range(0, 1)]
    public float holdDelay = 0.15f;

    [Header("달리기")]
    [Tooltip("Shift를 누르고 있는 동안 곱해지는 속도 배율입니다")]
    [Range(1, 3)]
    public float runMultiplier = 1.6f;

    private Hero hero;
    private Animator animator;
    private bool stepping = false;     // 한 칸을 걷는 중인지
    private Vector2 target;            // 이번 걸음의 도착 칸
    private Vector2 dir;               // 마지막으로 걸은 방향
    private float lastH = 0f;          // 지난 프레임의 입력
    private float lastV = 0f;
    private float holdTime = 0f;       // 같은 방향을 누르고 있는 시간
    private bool queued = false;       // 걷는 도중 새로 누른 입력 (도착하면 그 방향으로 한 칸 더)
    private float queuedH = 0f;
    private float queuedV = 0f;

    void Start()
    {
        hero = GetComponent<Hero>();
        animator = GetComponent<Animator>();     // 애니메이터 컴포넌트 (없으면 null)
        hero.position = Snap(hero.position);     // 칸 가운데에서 시작
    }

    void Update()
    {
        // 왼쪽 -1 · 오른쪽 +1 / 위 -1 · 아래 +1
        float h = Input.GetAxisRaw("Horizontal");
        float v = Input.GetAxisRaw("Vertical");

        // 두 방향을 함께 누르면 지금 걷던 축을 그대로 (대각선 없음)
        if (h != 0 && v != 0)
        {
            if (dir.x != 0)
                v = 0;
            else
                h = 0;
        }
        bool pressing = h != 0 || v != 0;
        bool fresh = pressing && (h != lastH || v != lastV);   // 방금 눌렀거나 방향을 바꿈
        lastH = h;
        lastV = v;
        if (fresh)
            holdTime = 0f;
        if (pressing)
            holdTime += Time.deltaTime;
        else
            holdTime = 0f;

        if (!stepping)
        {
            // 새로 누르면 한 칸 · 오래 누르고 있으면 계속
            if (fresh || (pressing && holdTime >= holdDelay))
                StartStep(h, v);
        }
        else if (fresh)
        {
            queued = true;
            queuedH = h;
            queuedV = v;
        }

        if (stepping)
        {
            float s = speed;
            if (Input.GetKey(KeyCode.LeftShift))
                s = s * runMultiplier;

            // 이번 프레임에 걸을 거리 — 칸에 도착하고 남은 거리는 다음 칸으로 이어서 씁니다 (칸마다 끊기지 않게)
            float budget = s * Time.deltaTime;
            Vector2 next = Vector2.MoveTowards(hero.position, target, budget);
            budget = budget - Vector2.Distance(hero.position, next);
            if (!hero.Move(next - hero.position))
            {
                // 걷는 도중 길이 막히면(몬스터가 끼어듦 등) 가까운 칸 가운데로 돌아갑니다
                target = Snap(hero.position);
                budget = 0f;
            }
            if (Vector2.Distance(hero.position, target) < 0.01f)
            {
                hero.position = target;          // 칸 가운데에 딱 맞춤
                stepping = false;
                // 걷는 도중 다시 눌렀거나 오래 누르고 있으면 멈추지 않고 다음 칸으로
                if (queued)
                    StartStep(queuedH, queuedV);
                else if (pressing && holdTime >= holdDelay)
                    StartStep(h, v);
                queued = false;
                // 남은 거리만큼 다음 칸으로 바로 출발
                if (stepping && budget > 0f)
                {
                    Vector2 more = Vector2.MoveTowards(hero.position, target, budget);
                    hero.Move(more - hero.position);
                }
            }
        }

        // 애니메이터 창의 상태(대기_아래, 걷기_오른쪽 …)가 이 파라미터로 바뀝니다
        if (animator != null)
            animator.SetBool("IsMoving", stepping);
    }

    // 옆 칸으로 한 걸음을 시작합니다 (막혀 있으면 바라보기만)
    void StartStep(float h, float v)
    {
        dir = new Vector2(h, v);
        hero.Face(dir);                          // 바라보는 방향 (공격·손전등 방향에 쓰임)
        if (animator != null)
            animator.SetInteger("Dir", DirIndex(h, v));

        if (!hero.canMove)                       // 대화 중에는 움직이지 않음
            return;
        if (!hero.CanMove(dir))                  // 막힌 칸이면 바라보기만
            return;

        target = Snap(hero.position) + dir;
        stepping = true;
    }

    // 가장 가까운 칸 가운데 좌표
    Vector2 Snap(Vector2 p)
    {
        return new Vector2(Mathf.Round(p.x), Mathf.Round(p.y));
    }

    // 입력 방향 → 애니메이터 Dir 값
    int DirIndex(float h, float v)
    {
        if (Mathf.Abs(h) > Mathf.Abs(v))
            return h < 0 ? 2 : 3;
        return v < 0 ? 1 : 0;
    }
}

using UnityEngine;

// 주인공 행동 스크립트 (말 걸기 · 공격)
// 주인공 컴포넌트를 추가하면 함께 붙습니다. Space · Z · Enter 를 누르면
//   ① 가까이에 OnInteract()를 가진 오브젝트(NPC 등)가 있으면 그 오브젝트의 OnInteract()를 부르고
//   ② 없으면 바라보는 방향으로 공격합니다.
// 키·공격력·사거리를 바꾸거나, 공격 대신 다른 행동을 넣어도 됩니다.
public class HeroCombat : MonoBehaviour
{
    [Header("공격")]
    [Tooltip("한 번 공격할 때 몬스터에게 주는 피해입니다")]
    public int damage = 1;

    [Tooltip("공격이 닿는 거리(칸)입니다")]
    public float reach = 0.7f;

    [Header("말 걸기")]
    [Tooltip("이 거리(칸) 안에 있는 NPC 등에게 말을 겁니다")]
    public float talkDistance = 1.4f;

    private Hero hero;

    void Start()
    {
        hero = GetComponent<Hero>();
    }

    void Update()
    {
        bool pressed = Input.GetKeyDown(KeyCode.Space) || Input.GetKeyDown(KeyCode.Z) || Input.GetKeyDown(KeyCode.Return);
        if (!pressed)
        {
            return;
        }

        // 가까운 대상의 OnInteract()를 부릅니다 (NpcTalk 스크립트 → 대화창)
        if (hero.Interact(talkDistance))
        {
            return;
        }

        // 맞은 몬스터는 체력이 줄고 뒤로 밀려납니다. OnHit()을 가진 오브젝트에는 OnHit()을 보냅니다
        hero.Attack(damage, reach);
    }
}
